<script setup lang="ts">
import { nextTick, onBeforeUnmount, ref } from 'vue'
import type { User } from '../types'

const props = defineProps<{ currentUser: User }>()
const emit = defineEmits<{ alert: [msg: string, type?: 'success' | 'error'] }>()
const open = ref(false), loading = ref(false), sending = ref(false), input = ref('')
const conversation = ref<any>(null), messages = ref<any[]>([]), end = ref<HTMLElement | null>(null)
let timer: ReturnType<typeof setInterval> | null = null
const quick = ['我的积分 / 充值问题', '3D 材质与模型问题', '审核 / 打样进度', '博物馆合作与售卖', '版权与确权咨询']
function scroll() { nextTick(() => end.value?.scrollIntoView({ behavior: 'smooth' })) }
async function request(url: string, options?: RequestInit) { const r=await fetch(url, options); const d=await r.json().catch(()=>null); if(!r.ok) throw new Error(d?.message||`HTTP ${r.status}`); return d }
async function load(opening=false) {
  if (loading.value) return; loading.value=true
  try { const d = opening ? await request('/api/customer-service/conversations/open',{method:'POST'}) : await request('/api/customer-service/conversations/mine'); conversation.value=d.conversation; messages.value=d.messages||[]; scroll() }
  catch(e:any) { if(opening) emit('alert','客服连接失败：'+(e?.message||e),'error') }
  finally { loading.value=false }
}
async function toggle() { open.value=!open.value; if(open.value) { await load(true); if(timer) clearInterval(timer); timer=setInterval(()=>{ if(open.value) load() },10000) } else if(timer) { clearInterval(timer); timer=null } }
async function send(text?: string) { const content=(text||input.value).trim(); if(!content||sending.value||!conversation.value) return; sending.value=true; input.value=''; try { const d=await request(`/api/customer-service/conversations/${conversation.value.id}/messages`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({content})}); messages.value=d.messages||[]; scroll() } catch(e:any) { emit('alert','发送失败：'+(e?.message||e),'error') } finally { sending.value=false } }
function keydown(e:KeyboardEvent){if(e.key==='Enter'&&!e.shiftKey){e.preventDefault();send()}}
onBeforeUnmount(()=>{if(timer)clearInterval(timer)})
</script>
<template>
  <button class="support-fab" @click="toggle" :class="{open}" aria-label="打开客服助手"><span>✦</span><b>客服</b><i v-if="!open">AI</i></button>
  <Transition name="support-pop"><section v-if="open" class="support-panel"><header><div class="support-avatar">✦</div><div><span>SMART CARE · 在线</span><b>之间智造客服助手</b><small>{{ conversation?.humanTakeover ? `人工客服已接入${conversation?.takenByName ? ' · ' + conversation.takenByName : ''}` : 'AI 首响 · 人工客服可继续跟进' }}</small></div><button @click="toggle">×</button></header><main><div v-if="loading&&!messages.length" class="support-loading">正在连接客服...</div><template v-else><article v-for="m in messages" :key="m.id" :class="['support-message',m.senderType]"><span v-if="m.senderType!=='user'">{{ m.senderType==='staff'?'人':'AI' }}</span><div><p>{{ m.content }}</p><small>{{ m.senderType==='staff'?'人工客服':m.senderType==='assistant'?'AI 客服助手':'我' }}</small></div></article><div v-if="conversation?.humanTakeover" class="handoff-note">人工客服已接入，本次会话后续消息将由人工客服处理。</div><div v-else class="support-quick"><button v-for="item in quick" :key="item" @click="send(item)">{{ item }}</button></div><div ref="end" /></template></main><footer><textarea v-model="input" rows="1" placeholder="描述你的问题，AI 与人工客服都会看到" @keydown="keydown"></textarea><button :disabled="sending||!input.trim()" @click="send()">{{ sending?'…':'发送' }}</button></footer></section></Transition>
</template>
<style scoped>
.support-fab{position:fixed;z-index:60;right:20px;bottom:92px;display:flex;align-items:center;gap:7px;height:49px;padding:0 13px;border:0;border-radius:17px;background:linear-gradient(135deg,#132c2b,#0f766e 62%,#18a999);color:#fff;box-shadow:0 15px 34px rgba(10,76,70,.35);font-family:inherit}.support-fab span{display:grid;place-items:center;width:23px;height:23px;border-radius:8px;background:rgba(255,255,255,.15)}.support-fab b{font-size:13px}.support-fab i{padding:2px 5px;border-radius:8px;background:#f6c975;color:#49310c;font-size:9px;font-style:normal;font-weight:900}.support-panel{position:fixed;z-index:61;right:14px;bottom:150px;width:min(390px,calc(100vw - 28px));overflow:hidden;border:1px solid rgba(15,118,110,.15);border-radius:24px;background:#fffdf9;box-shadow:0 28px 70px rgba(27,31,30,.28)}.support-panel header{display:flex;align-items:center;gap:10px;padding:14px;background:linear-gradient(135deg,#14312f,#0f766e);color:#fff}.support-avatar{display:grid;place-items:center;width:36px;height:36px;border-radius:12px;background:rgba(255,255,255,.14)}.support-panel header div{min-width:0;flex:1}.support-panel header span,.support-panel header small{display:block;font-size:9px;color:#b8eee6;letter-spacing:.08em}.support-panel header b{display:block;margin:2px 0;font-size:14px}.support-panel header button{border:0;background:transparent;color:#fff;font-size:25px}.support-panel main{height:340px;overflow:auto;padding:13px;background:linear-gradient(180deg,#fffdf9,#f3faf8)}.support-message{display:flex;gap:7px;margin-bottom:11px;max-width:92%}.support-message>span{display:grid;place-items:center;width:23px;height:23px;border-radius:8px;background:#0f766e;color:#fff;font-size:9px;font-weight:900;flex:none}.support-message>div{padding:9px 11px;border-radius:4px 14px 14px;background:#fff;border:1px solid #e4ece9;box-shadow:0 3px 9px rgba(25,66,57,.05)}.support-message p{margin:0;white-space:pre-wrap;color:#334155;font-size:12px;line-height:1.55}.support-message small{display:block;margin-top:4px;color:#94a3b8;font-size:9px}.support-message.user{margin-left:auto;justify-content:flex-end}.support-message.user>div{border:0;border-radius:14px 4px 14px 14px;background:#0f766e;color:#fff}.support-message.user p,.support-message.user small{color:#fff}.support-quick{display:flex;flex-wrap:wrap;gap:6px;margin:8px 0}.support-quick button{border:1px solid #cae9e1;border-radius:99px;padding:5px 8px;background:#fff;color:#0f766e;font-size:10px}.support-panel footer{display:flex;gap:8px;padding:10px;border-top:1px solid #e5eeeb;background:#fff}.support-panel textarea{flex:1;resize:none;border:1px solid #d6e6e1;border-radius:12px;padding:8px;font:12px inherit;outline:0}.support-panel footer button{border:0;border-radius:12px;padding:0 12px;background:#0f766e;color:#fff;font-weight:800}.support-panel footer button:disabled{opacity:.45}.support-loading{padding:30px 0;text-align:center;color:#64748b;font-size:12px}.support-pop-enter-active,.support-pop-leave-active{transition:.2s}.support-pop-enter-from,.support-pop-leave-to{opacity:0;transform:translateY(12px) scale(.97)}
</style>
